const sail = (a) => { let x = 90, y = 340, h = -1.2, v = 0, T = 0, idx = 0, turn = 0; const B = [[190, 90], [410, 330], [640, 80], [520, 240], [240, 210], [90, 70], [620, 350], [360, 60]]; const wind = Math.PI / 2; let tx = null, ty = null; return { move: (p, q) => { tx = p; ty = q; }, tick(dt) { T += dt; turn = (a.keys.has("ArrowRight") || a.keys.has("d") ? 1 : 0) - (a.keys.has("ArrowLeft") || a.keys.has("a") ? 1 : 0); if (!turn && tx != null) { const want = Math.atan2(ty - y, tx - x), e = Math.atan2(Math.sin(want - h), Math.cos(want - h)); turn = clamp(e * 3, -1, 1); } h += turn * 2.5 * dt; const off = Math.abs(Math.atan2(Math.sin(h - wind), Math.cos(h - wind))), eff = off > 2.55 ? .16 : .45 + Math.sin(off) * .55; v += (235 * eff - v) * Math.min(1, dt * 1.7); x += Math.cos(h) * v * dt; y += Math.sin(h) * v * dt; if (x < 14 || x > AW - 14) { x = clamp(x, 14, AW - 14); v *= .5; } if (y < 14 || y > AH - 14) { y = clamp(y, 14, AH - 14); v *= .5; } const b = B[idx]; if (Math.hypot(b[0] - x, b[1] - y) < 34) { idx++; a.add(5); a.tone(620 + idx * 40); if (idx >= B.length) { a.add(Math.max(0, Math.round(a.left() / 2))); a.end(); } } }, draw(g, t) { g.fillStyle = "#2f7fa8"; g.fillRect(0, 0, AW, AH); g.strokeStyle = "rgba(255,255,255,.3)"; g.lineWidth = 2; for (let i = 0; i < 26; i++) { const px = (i * 67) % AW, py = (i * 41 + t * 46) % AH; g.beginPath(); g.moveTo(px, py); g.quadraticCurveTo(px + 9, py + 5, px + 18, py); g.stroke(); } g.strokeStyle = "rgba(255,255,255,.65)"; g.lineWidth = 3; g.beginPath(); g.moveTo(AW - 44, 40); g.lineTo(AW - 44, 82); g.lineTo(AW - 52, 72); g.moveTo(AW - 44, 82); g.lineTo(AW - 36, 72); g.stroke(); txt(g, "Wind", AW - 44, 34, "#fff", "800 11px system-ui"); B.forEach((b, i) => { if (i < idx) return; g.fillStyle = i === idx ? "#ffd27a" : "rgba(255,255,255,.35)"; g.beginPath(); g.arc(b[0], b[1], i === idx ? 17 : 11, 0, 7); g.fill(); txt(g, i + 1, b[0], b[1] + 5, "#1b2a3a", "900 13px system-ui"); }); g.save(); g.translate(x, y); g.rotate(h); g.fillStyle = "#7a4a2c"; g.beginPath(); g.moveTo(26, 0); g.lineTo(-20, -11); g.lineTo(-20, 11); g.fill(); g.fillStyle = "#fff"; g.beginPath(); g.moveTo(8, 0); g.quadraticCurveTo(-6, 22, -18, 2); g.fill(); g.restore(); txt(g, "Sailing straight into the wind barely moves. Tack across it.", AW / 2, AH - 12, "#dff2ff", "700 13px system-ui"); } }; };
const seal = (a) => { const N = 5; let g0 = Array(25).fill(0), cur = 12, round = 1, moves = 0, par = 0; const flip = (b, i) => { for (const k of [i, i % N ? i - 1 : -1, i % N < N - 1 ? i + 1 : -1, i - N, i + N]) if (k >= 0 && k < 25) b[k] ^= 1; }, deal = () => { g0 = Array(25).fill(0); par = Math.min(9, round + 2); const used = new Set(); while (used.size < par) used.add(Math.floor(Math.random() * 25)); for (const i of used) flip(g0, i); moves = 0; }; deal(); const hit = (i) => { flip(g0, i); moves++; a.tone(g0[i] ? 300 : 520, .05); if (g0.every((v) => !v)) { a.add(Math.max(2, 6 + par - moves)); a.tone(880); round++; deal(); } }; const S = 66, ox = 96, oy = 40; return { down: (x, y) => { const i = Math.floor((x - ox) / S), j = Math.floor((y - oy) / S * 1); if (i >= 0 && j >= 0 && i < N && j < N) { cur = j * N + i; hit(cur); } }, key: (k) => { if (k === "ArrowLeft") cur = cur % N ? cur - 1 : cur; if (k === "ArrowRight") cur = cur % N < N - 1 ? cur + 1 : cur; if (k === "ArrowUp") cur = cur >= N ? cur - N : cur; if (k === "ArrowDown") cur = cur < 20 ? cur + N : cur; if (k === " ") hit(cur); }, tick() {}, draw(g) { g.fillStyle = "#231a33"; g.fillRect(0, 0, AW, AH); g0.forEach((v, i) => { const x = ox + (i % N) * S, y = oy + Math.floor(i / N) * S; g.fillStyle = v ? "#c8322e" : "#4a3f5e"; g.beginPath(); g.roundRect(x + 4, y + 4, S - 8, S - 8, 10); g.fill(); if (v) { g.strokeStyle = "#ffd27a"; g.lineWidth = 2; g.beginPath(); g.arc(x + S / 2, y + S / 2, 15, 0, 7); g.stroke(); } if (i === cur) { g.strokeStyle = "#fff"; g.lineWidth = 3; g.beginPath(); g.roundRect(x + 3, y + 3, S - 6, S - 6, 10); g.stroke(); } }); txt(g, `Seal ${round}`, 560, 110, "#ffd27a", "900 28px system-ui"); txt(g, `Moves ${moves} · Par ${par}`, 560, 140, "#d9cfe8"); txt(g, "Pressing a stamp flips it", 560, 190, "#a89fba", "700 13px system-ui"); txt(g, "and the four beside it.", 560, 209, "#a89fba", "700 13px system-ui"); txt(g, "Clear every red seal.", 560, 228, "#a89fba", "700 13px system-ui"); } }; };

